import random
import time
import requests

def call_with_backoff(url: str, max_attempts: int = 5) -> dict:
    """Exponential backoff with full jitter to prevent retry storms."""
    base = 0.5   # seconds
    cap  = 30.0  # max wait seconds

    for attempt in range(max_attempts):
        try:
            resp = requests.get(url, timeout=2)
            resp.raise_for_status()
            return resp.json()
        except (requests.Timeout, requests.HTTPError) as e:
            if attempt == max_attempts - 1:
                raise
            # Full jitter: random in [0, min(cap, base * 2^attempt)]
            wait = random.uniform(0, min(cap, base * (2 ** attempt)))
            time.sleep(wait)

