import threading

class MonotonicCounter:
    """Thread-safe monotonic counter. Replace with distributed
    implementation (Redis INCR, ZooKeeper sequential node) for multi-node use."""

    def __init__(self, start: int = 0):
        self._value = start
        self._lock = threading.Lock()

    def next(self) -> int:
        with self._lock:
            self._value += 1
            return self._value

    @property
    def current(self) -> int:
        return self._value

